ALTER TABLE characters ADD COLUMN IF NOT EXISTS Skills JSON NOT NULL DEFAULT '[]';
ALTER TABLE characters ADD COLUMN IF NOT EXISTS InfoTask JSON NOT NULL DEFAULT '{}';

CREATE TABLE IF NOT EXISTS task_template (
    id SMALLINT PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    description VARCHAR(500) NOT NULL,
    npc_id SMALLINT NOT NULL,
    previous_id SMALLINT NOT NULL,
    `event` VARCHAR(20) NOT NULL,
    target_id INT NOT NULL,
    required_count INT NOT NULL,
    reward_tu_vi BIGINT NOT NULL,
    reward_points INT NOT NULL,
    reward_item_id SMALLINT NOT NULL,
    reward_quantity INT NOT NULL,
    FOREIGN KEY (npc_id) REFERENCES npc_template(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

