ALTER TABLE skill_template ADD COLUMN IF NOT EXISTS is_implemented BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE skill_template ADD COLUMN IF NOT EXISTS teacher_npc_id SMALLINT NOT NULL DEFAULT 0;
ALTER TABLE realm_template ADD COLUMN IF NOT EXISTS is_implemented BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE realm_template ADD COLUMN IF NOT EXISTS next_realm_id INT NOT NULL DEFAULT 0;
ALTER TABLE realm_template ADD COLUMN IF NOT EXISTS tu_vi_required BIGINT NOT NULL DEFAULT 0;
ALTER TABLE realm_template ADD COLUMN IF NOT EXISTS point_reward INT NOT NULL DEFAULT 0;
ALTER TABLE realm_template ADD COLUMN IF NOT EXISTS requires_trial BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE realm_template ADD COLUMN IF NOT EXISTS required_task_id SMALLINT NOT NULL DEFAULT 0;

UPDATE realm_template SET
    is_implemented=TRUE,
    next_realm_id=IF(id<11,id+1,0),
    tu_vi_required=IF(id=1,0,100+(id-2)*50),
    point_reward=IF(id=1,0,10),
    requires_trial=(id=2),
    required_task_id=IF(id=2,4,0)
WHERE id BETWEEN 1 AND 11 AND NOT EXISTS(SELECT 1 FROM tutien_schema WHERE id=5);

